  var st = curState();
  return { on:audio.enabled(), key:BF_SOUND_KEY, dir:BF_AUDIO_DIR,
           tickAt:TICK_AT, tickNear:TICK_NEAR, gapFar:TICK_GAP_FAR, gapNear:TICK_GAP_NEAR,
